```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true`, so a node that cannot get its notification
/// accepted traps rather than report a false or misleading result.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Author-granted extension (aap:caps/state-rw@0.1.0): record the input
        // this invocation received in the shared store, under `last-input`.
        state_rw::put("last-input", &feed_url);

        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: one permitted fetch. A transport failure is a value. It counts as
        // zero characters fetched and does not fail the heartbeat. A host outside
        // the allowlist traps at the boundary, which is the intended behaviour.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat on the digest channel.
        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // `ensures notified == true`: never emit an output that violates the
        // contract. If the channel would not accept the notification, trap.
        if !notified {
            panic!("notification was not accepted by the digest channel");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
